package com.civic.controller; import com.civic.dto.*; import com.civic.service.VoteService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/polls") @RequiredArgsConstructor public class VoteController {private final VoteService service; @PostMapping("/{pollId}/vote") @PreAuthorize("hasAnyRole('CITIZEN', 'OFFICIAL')") public ResponseEntity<VoteResponse> vote(@PathVariable Long pollId,@Valid @RequestBody VoteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.castVote(pollId,r));}}
